package main

import (
	"bufio"
	"fmt"
	"os"
)
func main() {
    leitor := bufio.NewScanner(os.Stdin)
    leitor.Scan()
    frase := leitor.Text()

    leitor.Scan()
    letra := leitor.Text()
    cont := 0

    for i := 0; i < len(frase); i++{
        if string(frase[i]) == letra {
            cont++
        }
    }
    fmt.Println(cont)
}
